"""Consistent third-person action captions; spoken dialogue stays natural."""
import re
VERBS={'подхожу':'подходит','наклоняюсь':'наклоняется','беру':'берёт','смотрю':'смотрит','улыбаюсь':'улыбается','обнимаю':'обнимает','целую':'целует','касаюсь':'касается','тянусь':'тянется','протягиваю':'протягивает','сажусь':'садится','сижу':'сидит','поворачиваюсь':'поворачивается','делаю':'делает','поправляю':'поправляет','отвожу':'отводит','киваю':'кивает','смеюсь':'смеётся','поднимаю':'поднимает','опускаю':'опускает','закрываю':'закрывает','открываю':'открывает','веду':'ведёт','прижимаю':'прижимает','шепчу':'шепчет','замечаю':'замечает'}
VERBS.update({'вздыхаю':'вздыхает','прохожу':'проходит','ставлю':'ставит','присаживаюсь':'присаживается','заправляю':'заправляет','прищуриваюсь':'прищуривается','прикусываю':'прикусывает','выхожу':'выходит','встаю':'встаёт','жду':'ждёт','пишу':'пишет','отвечаю':'отвечает','приближаюсь':'приближается','останавливаюсь':'останавливается','подмигиваю':'подмигивает','снимаю':'снимает','надеваю':'надевает','слушаю':'слушает','чувствую':'чувствует','думаю':'думает','прислоняюсь':'прислоняется','вглядываюсь':'вглядывается','разворачиваюсь':'разворачивается','приглашаю':'приглашает','замолкаю':'замолкает'})
def instruction(name):
 return (f'Имя персонажа — {name}. Внутри звёздочек описывай действия от третьего лица и называй персонажа этим именем: «*{name} подходит к тебе ближе.*». '
         'В обращении к пользователю всегда используй второе лицо: ты, тебя, тебе, к тебе, для тебя. Не называй пользователя «он», «она», «его», «её». '
         'В произнесённых репликах персонаж может говорить «я». Не приписывай пользователю действия и согласие. ')
def normalize(text,name):
 def action(match):
  value=match.group(1).strip()
  if re.match(r'^я\b',value,re.I):value=re.sub(r'^я\s*', '',value,flags=re.I)
  for first,third in VERBS.items():value=re.sub(r'\b'+first+r'\b',third,value,flags=re.I)
  value=re.sub(r'\bк (?:нему|ней)\b','к тебе',value,flags=re.I)
  value=re.sub(r'\bдля (?:него|неё|нее)\b','для тебя',value,flags=re.I)
  if not value.lower().startswith(name.lower()) and (re.match(r'\w+',value).group(0).lower() if re.match(r'\w+',value) else '') in set(VERBS.values()):value=name+' '+value[0].lower()+value[1:]
  return '*'+value+'*'
 return re.sub(r'(?<!\*)\*([^*\n]+)\*(?!\*)',action,text)
